type Tree = { l: Tree | null; r: Tree | null };

function makeTree(depth: number): Tree {
    if (depth === 0) {
        return { l: null, r: null };
    }
    return { l: makeTree(depth - 1), r: makeTree(depth - 1) };
}

function checkTree(t: Tree): number {
    if (t.l === null) {
        return 1;
    }
    return 1 + checkTree(t.l) + checkTree(t.r);
}

function main() {
    const n = parseInt(process.argv[2], 10);
    const minDepth = 4;
    const maxDepth = Math.max(minDepth + 2, n);
    const stretchDepth = maxDepth + 1;

    const out: string[] = [];

    // stretch tree
    const stretch = makeTree(stretchDepth);
    out.push(`stretch tree of depth ${stretchDepth}\t check: ${checkTree(stretch)}`);

    // long lived tree
    const longLived = makeTree(maxDepth);

    for (let d = minDepth; d <= maxDepth; d += 2) {
        const iterations = 1 << (maxDepth - d + minDepth);
        let check = 0;
        for (let i = 0; i < iterations; i++) {
            check += checkTree(makeTree(d));
        }
        out.push(`${iterations}\t trees of depth ${d}\t check: ${check}`);
    }

    out.push(`long lived tree of depth ${maxDepth}\t check: ${checkTree(longLived)}`);

    process.stdout.write(out.join("\n") + "\n");
}

